})
void testMixedCaseBooleanLiterals(String literal, boolean expected) {
  Assertions.assertDoesNotThrow((Executable) () -> {
    JsonReader reader = new JsonReader(reader("[" + literal + "]"));
    reader.beginArray();
    assertThat(reader.nextBoolean())
        .named("Literal '" + literal + "' should be parsed as " + expected)
        .isEqualTo(expected);
    reader.endArray();
    assertThat(reader.peek())
        .named("After reading boolean literal '" + literal + "', reader should be at END_DOCUMENT")
        .isEqualTo(END_DOCUMENT);
  });
}

