@FunctionalInterface
private interface ThrowingRunnable {
  void run() throws Exception;
}

@FunctionalInterface
private interface ThrowingSupplier<T> {
  T get() throws Exception;
}

private static void assertDoesNotThrow(ThrowingRunnable runnable, String message) {
  try {
    runnable.run();
  } catch (Exception e) {
    fail(message + ": " + e);
  }
}

private static <T> T assertDoesNotThrow(ThrowingSupplier<T> supplier, String message) {
  try {
    return supplier.get();
  } catch (Exception e) {
    fail(message + ": " + e);
    return null; // unreachable, required for compilation
  }
}

