@Test
public void testNewsHomepage() throws IOException {
    File in = getFile("/htmltests/news-com-au-home.html");
    Document doc = Jsoup.parse(in, "UTF-8", "http://www.news.com.au/");
    assertEquals("News.com.au | News from Australia and around the world online | NewsComAu", doc.title());
    assertEquals("Brace yourself for Metro meltdown", doc.select(".id1225817868581 h4").text().trim());

    Element a = doc.select("a[href=/entertainment/horoscopes]").first();
    assertEquals("/entertainment/horoscopes", a.attr("href"));
    assertEquals("http://www.news.com.au/entertainment/horoscopes", a.attr("abs:href"));

    Element hs = doc.select("a[href*=naughty-corners-are-a-bad-idea]").first();
    assertEquals(
            "http://www.heraldsun.com.au/news/naughty-corners-are-a-bad-idea-for-kids/story-e6frf7jo-1225817899003",
            hs.attr("href"));
    assertEquals(hs.attr("href"), hs.attr("abs:href"));
}

proposals.refactored:
@Test
public void testNewsHomepage(@TempDir File tempDir) {
    assertDoesNotThrow(() -> {
        File in = getFile("/htmltests/news-com-au-home.html");
        assertTrue(in.exists(), "Resource file should exist before parsing.");

        Document doc = Jsoup.parse(in, "UTF-8", "http://www.news.com.au/");

        assertEquals(
                "News.com.au | News from Australia and around the world online | NewsComAu",
                doc.title(),
                "Document title should match expected value.");

        assertEquals(
                "Brace yourself for Metro meltdown",
                doc.select(".id1225817868581 h4").text().trim(),
                "Headline text should match expected value.");

        Element a = doc.select("a[href=/entertainment/horoscopes]").first();
        assertEquals(
                "/entertainment/horoscopes",
                a.attr("href"),
                "Href attribute should be the relative path.");
        assertEquals(
                "http://www.news.com.au/entertainment/horoscopes",
                a.attr("abs:href"),
                "Absolute href should be correctly resolved.");

        Element hs = doc.select("a[href*=naughty-corners-are-a-bad-idea]").first();
        assertEquals(
                "http://www.heraldsun.com.au/news/naughty-corners-are-a-bad-idea-for-kids/story-e6frf7jo-1225817899003",
                hs.attr("href"),
                "Href attribute should match the expected URL.");
        assertEquals(
                hs.attr("href"),
                hs.attr("abs:href"),
                "Absolute href should be identical to href for this element.");
    }, "Unexpected exception occurred during the test execution.");
}

