// --- Helper methods -----------------------------------------------------

/**
 * Creates a fresh Document containing a paragraph with a <b> element.
 *
 * @return a new Document instance for each test
 */
private Document createDocument() {
    return Jsoup.parse("<p>One <b>two</b> three</p>");
}

/**
 * Creates the <em> element used in the tests.
 *
 * @return an {@code <em>} element containing the text "four"
 */
private Element createEmNode() {
    Element em = new Element(Tag.valueOf("em"), "");
    em.appendText("four");
    return em;
}

/**
 * Adds the <em> element after the first <b> element in the given document.
 *
 * @param doc the Document to modify
 */
private void addEmAfterB(Document doc) {
    Element em = createEmNode();
    doc.select("b").first().after(em);
