public void supportsClone_retainsClassAndText() {
    Document doc = createDocument();
    Element elClone = doc.clone().select("div").first();

    assertTrue("Cloned element should retain class 'foo'", elClone.hasClass("foo"));
    assertEquals("Cloned element should retain original text", "Text", elClone.text());
}

// Test that removing a class from the original does not affect the clone
@Test
public void supportsClone_originalRemoveClassDoesNotAffectClone() {
    Document doc = createDocument();
    Element original = selectDiv(doc);
    Element clone = doc.clone().select("div").first();

    original.removeClass("foo");

    assertFalse("Original element should no longer have class 'foo'", original.hasClass("foo"));
    assertTrue("Cloned element should still have class 'foo' after original modification", clone.hasClass("foo"));
}

