    Element original = selectDiv(doc);
    Element clone = doc.clone().select("div").first();

    original.text("None");

    assertEquals("Original element text should be updated to 'None'", "None", original.text());
    assertEquals("Cloned element text should remain 'Text' after original modification", "Text", clone.text());
}

