// Helper method to create the test element and verify basic node relationships
private Element getDiv(String html) {
    Document doc = Jsoup.parse(html);
    Element div = doc.selectFirst("div");
    // Ensure the element was found – guards against NullReturnValsMutator in Element.select
    assertNotNull("Div element should be present after parsing HTML.", div);
    // Verify structural relationships – guards against Node.parentNode and Node.nextSibling mutants
    assertNotNull("Div's parent node should not be null.", div.parentNode());
    assertNull("Div should not have a next sibling in this document structure.", div.nextSibling());
    return div;
}

